import sqlite3

DB_PATH = "crm.db"


def _reassign(conn, table, old_id, new_id):
    cur = conn.execute(
        f"UPDATE {table} SET contact_id = ? WHERE contact_id = ?",
        (new_id, old_id),
    )
    return cur.rowcount


