def merge_duplicate_contacts(primary_contact_id: int, duplicate_contact_id: int) -> dict:
    if primary_contact_id == duplicate_contact_id:
        return {"ok": False, "error": "contacts must differ"}
    conn = sqlite3.connect(DB_PATH)
    try:
        found = conn.execute(
            "SELECT COUNT(*) FROM contacts WHERE id IN (?, ?)",
            (primary_contact_id, duplicate_contact_id),
        ).fetchone()[0]
        if found != 2:
            return {"ok": False, "error": "contact not found"}
        moved_deals = _reassign(conn, "deals", duplicate_contact_id, primary_contact_id)
        moved_notes = _reassign(conn, "notes", duplicate_contact_id, primary_contact_id)
        conn.execute("DELETE FROM contacts WHERE id = ?", (duplicate_contact_id,))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "moved_deals": moved_deals, "moved_notes": moved_notes}
